export type UpdateResourceRequestDescription = string | null;

export type UpdateResourceRequestName = string | null;

export type UpdateResourceRequestResourceTypeId = null | ResourceTypeId;

/**
 * Request to update an existing resource. All fields optional (partial update).
 */
export interface UpdateResourceRequest {
  amenities?: UpdateResourceRequestAmenities;
  capacity?: UpdateResourceRequestCapacity;
  description?: UpdateResourceRequestDescription;
  name?: UpdateResourceRequestName;
  resource_type_id?: UpdateResourceRequestResourceTypeId;
}

export type UpdateScheduleRequestDescription = string | null;

export type UpdateScheduleRequestEffectiveUntil = string | null;

